    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            color, start = values[i], i
            while i < len(values) and values[i] == color:
                i += 1
            result.append((color, start, i - 1))
        return result

    top_runs, bottom_runs = runs(grid[0]), runs(grid[-1])
    top = max(top_runs, key=lambda x: x[2] - x[1]) if top_runs else None
    bottom = max(bottom_runs, key=lambda x: x[2] - x[1]) if bottom_runs else None
    horizontal = top is not None and bottom is not None and top[0] == bottom[0]

    if horizontal:
        rail_color, top_start, top_end = top
        _, bottom_start, bottom_end = bottom
        offset = bottom_start - top_start
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or color == rail_color:
                    continue
                dest = c + offset
                # Draw from each point toward its nearest horizontal rail;
                # ties reach both sides, leaving the rail cells untouched.
                dtop, dbottom = r, h - 1 - r
                if dtop <= dbottom:
                    for rr in range(1, r):
                        out[rr][c] = color
                if dbottom <= dtop:
                    for rr in range(r + 1, h - 1):
                        out[rr][c] = color
                out[r][c] = 4
                if 0 <= dest < w:
                    for rr in range(h):
                        if grid[rr][dest] != rail_color:
                            out[rr][dest] = color
        return out

    # Opposite vertical rails (left and right grid edges).
    left_runs = runs([grid[r][0] for r in range(h)])
    right_runs = runs([grid[r][-1] for r in range(h)])
    left = max(left_runs, key=lambda x: x[2] - x[1]) if left_runs else None
    right = max(right_runs, key=lambda x: x[2] - x[1]) if right_runs else None
    if left is None or right is None or left[0] != right[0]:
        return out
    rail_color, left_start, left_end = left
    _, right_start, right_end = right
    offset = right_start - left_start
    for r in range(h):
